// W37 Cal.com booking intake (17 Oct 2026). Run: node --test automation/tests/W37.test.mjs
// Logic: automation/lib/w37-cal.mjs. Structure: automation/W37.json (generated by automation/build-w37-cal.mjs).
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { createHmac } from 'node:crypto';
import * as L from '../lib/w37-cal.mjs';

const WF = JSON.parse(readFileSync(new URL('../W37.json', import.meta.url), 'utf8'));
const SECRET = 'test-secret-0123456789abcdef';
const CONSENT_LABEL = 'I agree that SortMyCover may message me on WhatsApp to book and remind me about my call, and may share my details with an adviser from an FSCA-authorised financial services provider. I am 18 or older. I can opt out by replying STOP.';
const body = (over = {}, pay = {}) => ({
  triggerEvent: 'BOOKING_CREATED', createdAt: '2026-10-17T13:00:00.000Z',
  payload: {
    uid: 'bk7Hq2xYz91', title: 'SortMyCover adviser call', startTime: '2026-10-21T08:00:00.000Z', endTime: '2026-10-21T08:30:00.000Z',
    organizer: { name: 'Mark Weston', email: 'MarkW@OracleBrokers.com', timeZone: 'Africa/Johannesburg' },
    attendees: [{ name: 'Lerato Dlamini', email: 'lerato@example.com', timeZone: 'Africa/Johannesburg' }],
    location: 'integrations:office365_video',
    responses: {
      name: { label: 'Your name', value: 'Lerato Dlamini' }, email: { label: 'Email address', value: 'Lerato@Example.com' },
      attendeePhoneNumber: { label: 'WhatsApp number', value: '+27 82 123 4567' },
      whatsapp_consent: { label: CONSENT_LABEL, value: true },
      ref: { label: 'ref', value: 'w-learn-bond via fb/cycle1-bond/carousel-2' },
    },
    ...pay,
  },
  ...over,
});
const BROKER = { id: 'b-mark', contact_person: 'Mark Weston' };

test('signature: hex HMAC-SHA256 of the raw body; wrong, missing, or no secret -> refused', () => {
  const raw = JSON.stringify(body());
  const sig = createHmac('sha256', SECRET).update(raw).digest('hex');
  assert.deepEqual(L.verifyCalSignature(raw, sig, SECRET), { ok: true });
  assert.deepEqual(L.verifyCalSignature(raw, `sha256=${sig}`, SECRET), { ok: true });
  assert.equal(L.verifyCalSignature(raw + ' ', sig, SECRET).reason, 'bad_signature');
  assert.equal(L.verifyCalSignature(raw, '', SECRET).reason, 'no_signature');
  assert.equal(L.verifyCalSignature(raw, sig, '').reason, 'no_secret');
});

test('normalise: number to +27, email lower-case, consent checkbox + wording, ref page + via, Teams for Office 365', () => {
  const e = L.normaliseCal(body());
  assert.equal(e.ok, true);
  assert.equal(e.phone, '+27821234567');
  assert.equal(e.email, 'lerato@example.com');
  assert.equal(e.first_name, 'Lerato');
  assert.equal(e.organizer_email, 'markw@oraclebrokers.com');
  assert.deepEqual(e.consent, { field: 'whatsapp_consent', given: true, text: CONSENT_LABEL });
  assert.deepEqual(e.ref, { page_ref: 'w-learn-bond', via: { source: 'fb', campaign: 'cycle1-bond', content: 'carousel-2' } });
  assert.equal(e.method, 'teams');
  assert.equal(L.normaliseCal(body({}, { responses: { ...body().payload.responses, attendeePhoneNumber: { value: '082 123 4567' } } })).phone, '+27821234567');
  // a renamed checkbox is still found by its wording
  const r = { ...body().payload.responses }; delete r.whatsapp_consent; r.consent_box = { label: CONSENT_LABEL, value: true };
  assert.equal(L.normaliseCal(body({}, { responses: r })).consent.given, true);
  assert.equal(L.normaliseCal({ triggerEvent: 'PING', payload: {} }).reason, 'ping');
  assert.equal(L.normaliseCal(body({}, { uid: 'x' })).reason, 'uid');
  assert.equal(L.methodOf('integrations:zoom'), 'zoom');
  assert.equal(L.methodOf('integrations:google:meet'), 'meet');
  assert.equal(L.methodOf('+27821234567'), 'phone');
  assert.equal(L.whenText('2026-10-21T08:00:00.000Z'), 'Wed 21 Oct at 10:00');
});

test('plan BOOKING_CREATED: lead with Cal.com consent + provenance, appointment, lead_optins row, confirm template', () => {
  const p = L.planCal(L.normaliseCal(body()), { broker: BROKER, lead: null, suppressed: false }, { now: '2026-10-17T13:00:01Z', brandId: 'brand-smc' });
  assert.equal(p.action, 'book');
  assert.equal(p.lead.consent_source, 'calcom');
  assert.equal(p.lead.consent_text_version, 'CONSENT-CALCOM-v1');
  assert.equal(p.lead.consent_text, CONSENT_LABEL);
  assert.equal(p.lead.consent_at, '2026-10-17T13:00:00.000Z');
  assert.deepEqual([p.lead.origin, p.lead.source, p.lead.ref, p.lead.utm_source, p.lead.utm_campaign, p.lead.utm_content], ['page', 'website_form', 'w-learn-bond', 'fb', 'cycle1-bond', 'carousel-2']);
  assert.equal(p.lead.provenance.door, 'calcom');
  assert.equal(p.lead.provenance.booking_uid, 'bk7Hq2xYz91');
  assert.deepEqual([p.appointment.method, p.appointment.status, p.appointment.booked_via, p.appointment.idempotency_key], ['teams', 'booked', 'page', 'calcom:bk7Hq2xYz91']);
  assert.deepEqual([p.optin.ref_code, p.optin.via_source, p.optin.message_sid, p.optin.consent_version, p.optin.recorded_by], ['w-learn-bond', 'fb', 'calcom:bk7Hq2xYz91', 'CONSENT-CALCOM-v1', 'W37']);
  const s = L.confirmSend(p, 'appt-1', 'lead-1');
  assert.deepEqual(s, { to: '+27821234567', kind: 'template', template: 'booking_confirm_chat', variables: ['Lerato', 'Mark', 'Wed 21 Oct at 10:00'],
    buttons: [{ quick_reply: 'booking_chat_yes:appt-1' }], lead_id: 'lead-1', broker_id: 'b-mark', correlation: 'W37:confirm:calcom:bk7Hq2xYz91', caller: 'W37' });
  assert.equal(L.confirmSend(p, null, 'lead-1'), null, 'no appointment row -> no template');
  const tpl = JSON.parse(readFileSync(new URL('../templates/booking_confirm_chat.json', import.meta.url), 'utf8'));
  assert.equal(tpl.category, 'UTILITY');
  assert.equal((tpl.components[0].text.match(/\{\{\d\}\}/g) || []).length, s.variables.length);
  assert.equal(tpl.components[2].buttons[0].text, "Yes, let's chat");
});

test('plan: existing lead is reused; a STOPped number gets no template; campaign page -> campaign source', () => {
  const ev = L.normaliseCal(body({}, { responses: { ...body().payload.responses, ref: { value: 'a02' } } }));
  const p = L.planCal(ev, { broker: BROKER, lead: { id: 'lead-old' }, suppressed: true }, { brandId: 'b' });
  assert.equal(p.lead.id, 'lead-old');
  assert.equal(p.lead.existing, true);
  assert.equal(p.lead.source, 'campaign');
  assert.equal(p.lead.utm_source, null);
  assert.equal(p.send, null);
});

test('plan: no broker, no number, no consent -> escalate, nothing stored or sent', () => {
  const ev = L.normaliseCal(body());
  assert.match(L.planCal(ev, { broker: null }).reason, /no SortMyCover broker with calendar email markw@oraclebrokers.com/);
  assert.equal(L.planCal({ ...ev, phone: null }, { broker: BROKER }).action, 'escalate');
  assert.match(L.planCal({ ...ev, consent: { given: false } }, { broker: BROKER }).reason, /consent box not ticked/);
});

test('plan: reschedule links the old booking and sends nothing; cancel needs the known booking', () => {
  const ev = L.normaliseCal(body({ triggerEvent: 'BOOKING_RESCHEDULED' }, { uid: 'bkNEW000001', rescheduleUid: 'bk7Hq2xYz91' }));
  const p = L.planCal(ev, { broker: BROKER, lead: { id: 'lead-1' }, prev_appointment: { id: 'appt-old', reschedule_count: 1 } }, { brandId: 'b' });
  assert.equal(p.action, 'reschedule');
  assert.deepEqual([p.appointment.previous_booking_id, p.appointment.reschedule_count, p.appointment.idempotency_key, p.send], ['appt-old', 2, 'calcom:bkNEW000001', null]);
  const cev = L.normaliseCal(body({ triggerEvent: 'BOOKING_CANCELLED' }, { cancellationReason: 'Away that week' }));
  assert.equal(L.planCal(cev, {}).action, 'ignore');
  const cp = L.planCal(cev, { appointment: { id: 'appt-1', client_id: 'lead-1' } });
  assert.deepEqual([cp.action, cp.appointment_id, cp.activity.type, cp.activity.payload.reason], ['cancel', 'appt-1', 'calcom_cancelled', 'Away that week']);
});

test('W37.json: POST /cal, signature before anything, claim, one-statement upsert, optins never block, sends only via smc-whatsapp-send', () => {
  const nd = (x) => WF.nodes.find((n) => n.name === x);
  assert.equal(WF.id, 'smc-w37');
  assert.equal(WF.active, false);
  const wh = nd('POST /cal (Cal.com)');
  assert.deepEqual([wh.parameters.path, wh.parameters.httpMethod, wh.parameters.options.rawBody], ['cal', 'POST', true]);
  assert.match(nd('Verify signature + normalise (w37)').parameters.jsCode, /verifyCalSignature\(raw, h\['x-cal-signature-256'\], \$env\.CAL_WEBHOOK_SECRET\)/);
  assert.match(nd('Claim (other / calcom:<event>:<uid>)').parameters.query, /ON CONFLICT \(source, external_id\) DO NOTHING/);
  const up = nd('Book: lead + appointment + consent (one statement)').parameters.query;
  for (const k of ["'calcom', 'booked'", "INSERT INTO public.appointments", 'ON CONFLICT DO NOTHING', "'W37:' || $24 || ':' || $20", 'public.smc_hash_contact($4)']) assert.ok(up.includes(k), k);
  assert.equal(nd('Opt-in record (lead_optins)').onError, 'continueRegularOutput');
  const senders = WF.nodes.filter((n) => n.type === 'n8n-nodes-base.httpRequest');
  assert.equal(senders.length, 0, 'no direct HTTP sender: DRY_RUN and suppression live in smc-whatsapp-send');
  assert.equal(nd('WhatsApp Send (booking_confirm_chat)').parameters.workflowId.value, 'smc-whatsapp-send');
  const outs = (x, i) => (WF.connections[x].main[i] || []).map((t) => t.node);
  assert.deepEqual(outs('Action?', 0), ['Book: lead + appointment + consent (one statement)']);
  assert.deepEqual(outs('Action?', 3), ['Escalate (Cal.com, needs a person)']);
  assert.deepEqual(outs('Appointment stored?', 1), ['Escalate (booking not stored)']);
  assert.ok(!JSON.stringify(WF).includes(SECRET));
});
